from collections import deque

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(grid[0][0], 0, 0, [grid[0][0]])])
    visited = {(0, 0)}
    min_path = float('inf')

    while queue:
        path_sum, x, y, path = queue.popleft()
        if len(path) == k:
            if path < min_path:
                min_path = path
        else:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((path_sum + grid[nx][ny], nx, ny, path + [grid[nx][ny]]))

    return list(min_path)
